using Polhem.Core.Data;
using Polhem.Definition;
using Polhem.Definition.Database;

namespace Polhem.Db.Providers
{
    /// <summary>
    /// Decides which built-in default a <see cref="FieldDbType.Guid"/> column gets.
    /// </summary>
    /// <remarks>
    /// Only <see cref="SysFields.RowId"/> is generated by the database. Every other GUID column is a reference or a key the
    /// caller supplies, and its unset value is <see cref="System.Guid.Empty"/>, the value the framework reads as "no link".
    /// A generated default there turned a row written without the column (a seed, a hand-written INSERT, or the existing
    /// rows an ADD COLUMN backfills) into a link to a row that does not exist.
    /// </remarks>
    internal static class GuidColumnDefault
    {
        /// <summary>
        /// The text of <see cref="System.Guid.Empty"/> in the hyphenated form every dialect accepts.
        /// </summary>
        public const string EmptyGuidText = "00000000-0000-0000-0000-000000000000";

        /// <summary>
        /// The empty GUID as a quoted SQL literal.
        /// </summary>
        public const string EmptyGuidLiteral = "'" + EmptyGuidText + "'";

        /// <summary>
        /// Returns whether the database generates a new GUID for the field when a row is written without it.
        /// </summary>
        /// <param name="field">The field definition.</param>
        public static bool GeneratesNewGuid(DbField field)
        {
            return field.DbType == FieldDbType.Guid
                && string.Equals(field.FieldName, SysFields.RowId, StringComparison.OrdinalIgnoreCase);
        }
    }
}
